class Employee {
    private String name;
    private double baseSalary;
    public Employee(String name, double baseSalary) {
        this.name = name;
        this.baseSalary = baseSalary;
    }
    public double calculatePay() {
        return baseSalary;
    }
    public String getName() { return name; }
}

class Manager extends Employee {
    private double bonus;
    public Manager(String name, double baseSalary, double bonus) {
        super(name, baseSalary);
        this.bonus = bonus;
    }
    @Override
    public double calculatePay() {
        return super.calculatePay() + bonus;
    }
}

public class UpcastingDemo {
    // Accepts any Employee or subclass through upcasting
    public static void printPayStub(Employee emp) {
        System.out.println(emp.getName() + " Total Pay: $" + emp.calculatePay());
    }

    public static void main(String[] args) {
        Employee staff = new Employee("Bob", 50000.0);
        Manager mgr = new Manager("Alice", 90000.0, 20000.0);

        // Implicit upcast happens during method call
        printPayStub(staff);
        printPayStub(mgr); // Manager upcast to Employee automatically!
    }
}

