interface Printable {
    void print();
}
interface Exportable extends Printable {
    String exportJson();
}

class Invoice implements Exportable {
    private int invoiceId;
    public Invoice(int id) { this.invoiceId = id; }
    @Override
    public void print() {
        System.out.println("Printing Invoice #" + invoiceId);
    }
    @Override
    public String exportJson() {
        return "{\"invoiceId\": " + invoiceId + "}";
    }
}

public class InterfaceUpcastDemo {
    public static void main(String[] args) {
        Invoice inv = new Invoice(101);

        // 1. Upcast to immediate interface
        Exportable exp = inv;
        System.out.println(exp.exportJson());

        // 2. Upcast further up to root interface
        Printable p = exp;
        p.print();
    }
}

