interface MessageSender {
    void send(String recipient, String message);
}

class EmailSender implements MessageSender {
    @Override
    public void send(String recipient, String message) {
        System.out.println("EMAIL to " + recipient + ": " + message);
    }
}

class SlackSender implements MessageSender {
    @Override
    public void send(String recipient, String message) {
        System.out.println("SLACK to #" + recipient + ": " + message);
    }
}

class AlertService {
    public void broadcast(MessageSender sender, String target, String msg) {
        sender.send(target, msg);
    }
}

public class BroadcasterApp {
    public static void main(String[] args) {
        AlertService service = new AlertService();
        MessageSender email = new EmailSender();
        MessageSender slack = new SlackSender();

        service.broadcast(email, "admin@company.com", "Server high load");
        service.broadcast(slack, "dev-ops", "Deploy complete");
    }
}

abstract class StaffMember {
    protected String name;
    public StaffMember(String name) {
        this.name = name;
    }
    public abstract double getMonthlyEarnings();
}

class SalariedStaff extends StaffMember {
    private double monthlySalary;
    public SalariedStaff(String name, double monthlySalary) {
        super(name);
        this.monthlySalary = monthlySalary;
    }
    @Override
    public double getMonthlyEarnings() { return monthlySalary; }
}

class CommissionStaff extends StaffMember {
    private double basePay;
    private double salesAmount;
    private double commissionRate;
    public CommissionStaff(String name, double basePay, double salesAmount, double commissionRate) {
        super(name);
        this.basePay = basePay;
        this.salesAmount = salesAmount;
        this.commissionRate = commissionRate;
    }
    @Override
    public double getMonthlyEarnings() {
        return basePay + (salesAmount * commissionRate);
    }
}

public class PayrollApp {
    public static void main(String[] args) {
        StaffMember[] payroll = new StaffMember[] {
            new SalariedStaff("John Doe", 6000.0),
            new CommissionStaff("Jane Smith", 2500.0, 50000.0, 0.08)
        };
        for (StaffMember s : payroll) {
            System.out.println("Staff: " + s.name + " Earnings: $" + s.getMonthlyEarnings());
        }
    }
}

