public class ArrayCovarianceBug {
    public static void main(String[] args) {
        Integer[] numbers = new Integer[3];
        numbers[0] = 10;
        numbers[1] = 20;

        // Upcast Integer[] to Object[]
        Object[] objects = numbers;

        // BUG: Storing String into an underlying Integer[] throws ArrayStoreException!
        objects[2] = "oops";

        int sum = 0;
        for (Object o : objects) {
            sum += (Integer) o;
        }
        System.out.println("Sum: " + sum);
    }
}

