practiceProblems.solutionCode:
public class ArrayCovarianceBug {
    public static void main(String[] args) {
        Integer[] numbers = new Integer[3];
        numbers[0] = 10;
        numbers[1] = 20;
        numbers[2] = 0; // Fix: Store an Integer instead of incompatible String

        int sum = 0;
        for (Integer n : numbers) {
            sum += n;
        }
        System.out.println("Sum: " + sum);
    }
}

interface Filter {
    String apply(String input);
}

interface AuditedFilter extends Filter {
    String getFilterName();
}

class TrimFilter implements AuditedFilter {
    @Override
    public String apply(String input) { return input.trim(); }
    @Override
    public String getFilterName() { return "TrimFilter"; }
}

class UpperCaseFilter implements AuditedFilter {
    @Override
    public String apply(String input) { return input.toUpperCase(); }
    @Override
    public String getFilterName() { return "UpperCaseFilter"; }
}

class PipelineManager {
    public static String processAll(AuditedFilter[] filters, String text) {
        for (AuditedFilter f : filters) {
            System.out.println("Applying " + f.getFilterName());
            text = f.apply(text);
        }
        return text;
    }
}

public class PipelineApp {
    public static void main(String[] args) {
        AuditedFilter[] filters = new AuditedFilter[] {
            new TrimFilter(),
            new UpperCaseFilter()
        };
        String result = PipelineManager.processAll(filters, "   learn by self   ");
        System.out.println("Result: [" + result + "]");
    }
}
